package com.ds.goroute.controller;import com.ds.goroute.dto.BaseResponse;import com.ds.goroute.dto.request.UpsertPartnerPlaceRequest;import com.ds.goroute.dto.response.PartnerPlaceResponse;import com.ds.goroute.service.PartnerPlaceService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.authentication.AuthenticationCredentialsNotFoundException;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/v1/api/partner/places") @RequiredArgsConstructor public class PartnerPlaceController {private final PartnerPlaceService s;@GetMapping public ResponseEntity<BaseResponse<List<PartnerPlaceResponse>>> list(Authentication a,@RequestParam UUID organizationId){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.list(user(a),organizationId)));}@PostMapping public ResponseEntity<BaseResponse<PartnerPlaceResponse>> create(Authentication a,@Valid @RequestBody UpsertPartnerPlaceRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(BaseResponse.ofSucceeded(s.create(user(a),r)));}@PutMapping("/{id}")public ResponseEntity<BaseResponse<PartnerPlaceResponse>> update(Authentication a,@PathVariable UUID id,@Valid @RequestBody UpsertPartnerPlaceRequest r){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.update(user(a),id,r)));}private UUID user(Authentication a){if(a==null||a.getPrincipal()==null)throw new AuthenticationCredentialsNotFoundException("Authentication required");Object p=a.getPrincipal();return p instanceof UUID id?id:UUID.fromString(p.toString());}}
